def tech(rows):
    cards = "".join(f'<div class="card"><h3>{t}</h3><div class="tags">{"".join(f"<span>{x}</span>" for x in xs)}</div></div>' for t, xs in rows)
    return (f'<section class="section" aria-labelledby="tech-title"><div class="wrap"><div class="sec-head"><span class="eyebrow">Technology</span>'
            f'<h2 id="tech-title">Modern, proven <span class="grad-text">technology</span></h2></div><div class="cards">{cards}</div></div></section>')


